// Renders the home page from window.CATALOG (generated by tools/build.mjs).
// You normally never need to edit this file.
(function () {
  const C = window.CATALOG || { subjects: [] };
  const $ = id => document.getElementById(id);
  const esc = s => String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const url = h => h.split("/").map(encodeURIComponent).join("/");
  const fmtDate = d => d ? new Date(d + "T00:00:00").toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" }) : "";
  const isNew = d => d && (Date.now() - new Date(d + "T00:00:00")) / 864e5 <= (C.newForDays || 14);

  // ----- Header, stats -----
  document.title = C.title || document.title;
  $("site-title").textContent = $("hero-title").textContent = C.title || "Revision Notes";
  $("tagline").textContent = C.tagline || "";

  const all = C.subjects.flatMap(s => s.chapters.map(c => ({ ...c, subject: s })));
  const ready = c => !!c.updated;   // false = placeholder chapter (only title.txt so far)
  const nNotes = all.filter(c => c.notes.length).length;
  const nTests = all.reduce((n, c) => n + c.tests.length, 0);
  $("stats").innerHTML = [
    [C.subjects.length, "Subjects"], [all.length, "Chapters"], [nNotes, "Notes ready"], [nTests, "Test papers"],
  ].map(([n, l]) => `<li><strong>${n}</strong><span>${l}</span></li>`).join("");
  const last = all.map(c => c.updated).filter(Boolean).sort().pop();
  $("last-updated").textContent = fmtDate(last);

  // ----- Chapter card -----
  const card = c => {
    if (!ready(c)) return `
      <article class="chapter soon" data-subject="${esc(c.subject.id)}" data-soon="1" data-search="${esc((c.title + " " + c.subject.name).toLowerCase())}">
        ${c.num != null ? `<span class="ch-num">Ch ${c.num}</span>` : ""}
        <h3 class="chapter-title">${esc(c.title)}</h3>
        <span class="soon-label">Coming soon</span>
      </article>`;
    const main = c.notes[0];
    const extraNotes = c.notes.slice(1).map(n =>
      `<a class="chip chip-notes" href="${url(n.href)}">📝 ${esc(n.label)}</a>`).join("");
    const tests = c.tests.map(t =>
      `<a class="chip chip-test" href="${url(t.href)}" target="_blank" rel="noopener" title="Open PDF in a new tab">📄 ${esc(t.label)}</a>`).join("");
    const search = [c.title, c.subject.name, ...c.notes.map(n => n.label), ...c.tests.map(t => t.label)].join(" ").toLowerCase();
    return `
      <article class="chapter" data-subject="${esc(c.subject.id)}" data-search="${esc(search)}">
        <div class="chapter-head">
          ${c.num != null ? `<span class="ch-num">Ch ${c.num}</span>` : ""}
          ${isNew(c.updated) ? `<span class="badge-new">New</span>` : ""}
        </div>
        <h3 class="chapter-title">${main ? `<a href="${url(main.href)}">${esc(c.title)}</a>` : esc(c.title)}</h3>
        <div class="chapter-actions">
          ${main ? `<a class="btn" href="${url(main.href)}">Read notes →</a>` : `<span class="muted">Notes coming soon</span>`}
          ${extraNotes}
        </div>
        ${tests ? `<div class="tests"><span class="tests-label">Practice tests</span><div class="chips">${tests}</div></div>` : ""}
        <div class="chapter-foot">Updated ${fmtDate(c.updated)}</div>
      </article>`;
  };

  // ----- Library grouped by subject -----
  $("library").innerHTML = C.subjects.map(s => `
    <section class="subject" id="${esc(s.id)}" data-subject="${esc(s.id)}">
      <h2 class="subject-title"><span>${s.icon}</span> ${esc(s.name)}
        <small>${s.chapters.filter(ready).length} of ${s.chapters.length} chapters ready</small></h2>
      <div class="grid">${s.chapters.map(c => card({ ...c, subject: s })).join("")}</div>
    </section>`).join("");

  // ----- Recently added -----
  const recent = all.filter(c => isNew(c.updated)).sort((a, b) => b.updated.localeCompare(a.updated)).slice(0, 4);
  if (recent.length && all.length > 3) {
    $("recent").hidden = false;
    $("recent-list").innerHTML = recent.map(c => {
      const href = (c.notes[0] || c.tests[0]).href;
      return `<a class="recent-item" href="${url(href)}"><span>${c.subject.icon} ${esc(c.subject.name)}</span><strong>${esc(c.title)}</strong></a>`;
    }).join("");
  }

  // ----- Tabs + search -----
  let active = "all";
  const tabs = $("tabs");
  tabs.innerHTML = [{ id: "all", name: "All", icon: "" }, ...C.subjects].map(s =>
    `<button type="button" data-tab="${esc(s.id)}" aria-pressed="${s.id === "all"}">${s.icon ? s.icon + " " : ""}${esc(s.name)}</button>`).join("");
  if (C.subjects.length < 2) tabs.hidden = true;

  const search = $("search");
  const hideSoon = $("hide-soon");
  try { hideSoon.checked = localStorage.getItem("hideSoon") === "1"; } catch (e) {}
  hideSoon.addEventListener("change", () => { try { localStorage.setItem("hideSoon", hideSoon.checked ? "1" : "0"); } catch (e) {} apply(); });
  if (!all.some(c => !ready(c))) hideSoon.parentElement.hidden = true;
  function apply() {
    const words = search.value.toLowerCase().trim().split(/\s+/).filter(Boolean);
    let shown = 0;
    document.querySelectorAll(".subject").forEach(sec => {
      let any = false;
      sec.querySelectorAll(".chapter").forEach(el => {
        const ok = !(hideSoon.checked && el.dataset.soon) && (active === "all" || el.dataset.subject === active) && words.every(w => el.dataset.search.includes(w));
        el.hidden = !ok; if (ok) { any = true; shown++; }
      });
      sec.hidden = !any;
    });
    $("empty").hidden = shown > 0;
    $("recent").hidden = !!words.length || active !== "all" || !$("recent-list").children.length;
  }
  tabs.addEventListener("click", e => {
    const b = e.target.closest("button"); if (!b) return;
    active = b.dataset.tab;
    tabs.querySelectorAll("button").forEach(x => x.setAttribute("aria-pressed", x === b));
    apply();
  });
  search.addEventListener("input", apply);
  apply();
  document.addEventListener("keydown", e => {
    if (e.key === "/" && document.activeElement !== search) { e.preventDefault(); search.focus(); }
    if (e.key === "Escape" && document.activeElement === search) { search.value = ""; apply(); search.blur(); }
  });

  // ----- Theme toggle -----
  $("theme-toggle").addEventListener("click", () => {
    const root = document.documentElement;
    const dark = root.dataset.theme ? root.dataset.theme === "dark" : matchMedia("(prefers-color-scheme: dark)").matches;
    root.dataset.theme = dark ? "light" : "dark";
    try { localStorage.setItem("theme", root.dataset.theme); } catch (e) {}
  });
})();
